import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).strip();
        char[] st = new char[s.length()];
        int k = 0;
        for (int i = 0; i < s.length(); i++) {
            st[k++] = s.charAt(i);
            if (k >= 3 && st[k - 3] == 'A' && st[k - 2] == 'W' && st[k - 1] == 'S') k -= 3;
        }
        System.out.println(k == 0 ? "-1" : new String(st, 0, k));
    }
}

package main

import (
	"bufio"
	"bytes"
	"io"
	"os"
)

func main() {
	raw, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	s := bytes.TrimSpace(raw)
	st := make([]byte, 0, len(s)+1)
	for _, c := range s {
		st = append(st, c)
		if k := len(st); k >= 3 && st[k-3] == 'A' && st[k-2] == 'W' && st[k-1] == 'S' {
			st = st[:k-3]
		}
	}
	if len(st) == 0 {
		st = append(st, '-', '1')
	}
	os.Stdout.Write(append(st, '\n'))
}
